// Create a char array to store the characters of the string
char[] charArray = str.toString().toCharArray();

// Initialize the size variable to 0
int utf8Size = 0;

// Iterate over the characters of the string
for (int i = index; i < index + len; i++) {

// If the character is a 1-byte character, increment the size variable
if (charArray[i] <= 0x7F) {
utf8Size++;
}

// If the character is a 2-byte character, increment the size variable by 2
if (charArray[i] > 0x7F && charArray[i] <= 0x7FF) {
utf8Size += 2;
}

// If the character is a 3-byte character, increment the size variable by 3
if (charArray[i] > 0x7FF && charArray[i] <= 0xFFFF) {
utf8Size += 3;
}

// If the character is a 4-byte character, increment the size variable by 4
if (charArray[i] > 0xFFFF && charArray[i] <= 0x10FFFF) {
utf8Size += 4;
}
}

// Return the utf8 size
return utf8Size;
}

