public static String applyRelativePath(String path, String relativePath) {
    String result = "";
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        return result;
    }

    // Split the path and relative path into arrays of strings using "/" as the separator
    String[] pathArray = path.split("/");
    String[] relativePathArray = relativePath.split("/");

    // Create a new List to store the resulting path
    List<String> resultList = new ArrayList<>();

    // Add the first element of the relative path to the result list
    resultList.add(relativePathArray[0]);

    // Iterate over the remaining elements of the relative path
    for (int i = 1; i < relativePathArray.length; i++) {
        // If the element is "..", add the previous element of the path to the result list
        if (relativePathArray[i].equals("..")) {
            resultList.add(pathArray[pathArray.length - 1]);
        } else {
            // Add the element to the result list
            resultList.add(relativePathArray[i]);
        }
    }

    // Join the elements of the result list using "/" as the separator
    for (String element : resultList) {
        result += element + "/";
    }

    // Return the resulting path
    return result;
}

